/**
 * Model-based test: replay every behaviour of the TLA+ handshake model
 * (`Handshake.tla`, next to this file) into the real IrcClient and check
 * that Seance sends exactly the lines the model says it sends.
 *
 * Each trace is what one behaviour of the model looks like from Seance's
 * side: the server lines it handled (and SASL timer firings) in order, each
 * with how many lines Seance had sent before it, and the full list of lines
 * Seance sent. The traces are generated by TLC, not written by hand
 * (README.md says how). A mismatch means the model and the code disagree:
 * either the code has the bug the model predicts, or the model is wrong.
 */
import fs from "fs";
import path from "path";
import {expect} from "chai";
import sinon from "sinon";
import socket from "../../../client/js/socket";
import {IrcClient} from "../../../client/js/irc/client";
import {IdAllocator} from "../../../client/js/irc/ids";
import {SASL_TIMEOUT_MS} from "../../../client/js/irc/sasl";
import {trustLogin, useStorageBackend} from "../../../client/js/irc/saslTrust";
import type {Transport} from "../../../client/js/irc/types";
import type {TransportEvent, TransportState} from "../../../client/js/irc/transport";

type ModelMsg = {t: string; caps?: string[]};
type Trace = {
	creds: boolean;
	required: boolean;
	/** The login has worked on this network before (saslTrust.ts). */
	trusted: boolean;
	got: {m: ModelMsg; at: number}[];
	sent: ModelMsg[];
	outcome: "none" | "rejected" | "retry";
};

/** The model's abstract caps, as real cap names Seance wants. Order = Seance's REQ order. */
const CAP_NAME: Record<string, string> = {x: "server-time", y: "message-tags", sasl: "sasl"};
const LS_TOKEN: Record<string, string> = {...CAP_NAME, sasl: "sasl=PLAIN"};
const MODEL_CAP = Object.fromEntries(Object.entries(CAP_NAME).map(([k, v]) => [v, k]));

class FakeTransport implements Transport {
	state: TransportState = "closed";
	sent: string[] = [];
	abandonCalls: string[] = [];
	private listeners: ((ev: TransportEvent) => void)[] = [];

	on(listener: (ev: TransportEvent) => void): () => void {
		this.listeners.push(listener);
		return () => {
			this.listeners = this.listeners.filter((l) => l !== listener);
		};
	}

	connect(): void {
		this.state = "connecting";
	}

	send(line: string): void {
		if (this.state !== "open") {
			throw new Error("not open");
		}

		this.sent.push(line);
	}

	close(): void {
		this.state = "closed";
	}

	abandon(reason: string): void {
		this.abandonCalls.push(reason);
		this.state = "reconnect-wait";
		this.emit({
			type: "close",
			code: 1006,
			reason,
			wasClean: false,
			willReconnect: true,
			delayMs: 1000,
		});
	}

	open(): void {
		this.state = "open";
		this.emit({type: "open", subprotocol: "text.ircv3.net"});
	}

	line(line: string): void {
		this.emit({type: "line", line});
	}

	private emit(ev: TransportEvent): void {
		for (const listener of [...this.listeners]) {
			listener(ev);
		}
	}
}

function capList(caps: string[] | undefined, names: Record<string, string>): string {
	return Object.keys(CAP_NAME)
		.filter((c) => caps?.includes(c))
		.map((c) => names[c])
		.join(" ");
}

/** A server line the model's message stands for. */
function serverLine(m: ModelMsg): string {
	switch (m.t) {
		case "LS":
			return `:irc.test CAP * LS :${capList(m.caps, LS_TOKEN)}`;
		case "ACK":
		case "NAK":
			return `:irc.test CAP alice ${m.t} :${capList(m.caps, CAP_NAME)}`;
		case "AUTH+":
			return "AUTHENTICATE +";
		case "900":
			return ":irc.test 900 alice alice!alice@host alice :You are now logged in as alice";
		case "903":
			return ":irc.test 903 alice :SASL authentication successful";
		case "904":
			return ":irc.test 904 alice :SASL authentication failed";
		case "904T":
			return ":irc.test 904 alice :SASL authentication failed: request timed out";
		case "906":
			return ":irc.test 906 alice :SASL authentication aborted";
		case "907":
			return ":irc.test 907 alice :You have already authenticated using SASL";
		case "001":
			return ":irc.test 001 alice :Welcome to the test network, alice";
		default:
			throw new Error(`no server line for model message ${m.t}`);
	}
}

/** Seance's line as the model's message; null for lines the model leaves out. */
function modelOf(line: string): string | null {
	if (line === "CAP LS 302") {
		return "CAPLS";
	}

	if (line.startsWith("NICK ")) {
		return "NICK";
	}

	if (line.startsWith("USER ")) {
		return "USER";
	}

	if (line === "CAP END") {
		return "CAPEND";
	}

	if (line.startsWith("QUIT")) {
		return "QUIT";
	}

	if (line === "AUTHENTICATE *") {
		return "AUTHABORT";
	}

	if (line === "AUTHENTICATE PLAIN") {
		return "AUTH";
	}

	if (line.startsWith("AUTHENTICATE ")) {
		return "AUTHDATA";
	}

	if (line.startsWith("CAP REQ :")) {
		const caps = line
			.slice("CAP REQ :".length)
			.split(" ")
			.map((n) => MODEL_CAP[n] ?? `?${n}`)
			.sort();
		return `REQ(${caps.join(",")})`;
	}

	return null;
}

function show(m: ModelMsg): string {
	return m.caps ? `${m.t}(${[...m.caps].sort().join(",")})` : m.t;
}

/** Order inside a run of consecutive REQs is not something the model fixes. */
function canonical(lines: string[]): string[] {
	const out: string[] = [];
	let run: string[] = [];
	const flush = (): void => {
		out.push(...run.sort());
		run = [];
	};

	for (const l of lines) {
		if (l.startsWith("REQ(")) {
			run.push(l);
		} else {
			flush();
			out.push(l);
		}
	}

	flush();
	return out;
}

type Mismatch =
	| {expected: string[]; actual: string[]; at: number}
	| {outcome: string; seance: string};

/** How Seance left the connection, in the model's terms. */
function outcomeOf(rejected: number, transport: FakeTransport): string {
	if (rejected > 0) {
		return "rejected";
	}

	return transport.abandonCalls.length > 0 ? "retry" : "none";
}

function replay(trace: Trace): Mismatch | null {
	const clock = sinon.useFakeTimers();
	const transport = new FakeTransport();
	let rejected = 0;
	// Each behaviour starts from its own trust state: a success trusts the login.
	const store = new Map<string, string>();
	useStorageBackend({
		get: (key) => store.get(key) ?? null,
		set: (key, value) => void store.set(key, value),
		remove: (key) => void store.delete(key),
	});

	try {
		const client = new IrcClient({
			host: "irc.test",
			port: 6697,
			tls: true,
			nick: "alice",
			join: "",
			sasl: trace.creds ? "plain" : "",
			saslAccount: trace.creds ? "alice" : "",
			saslPassword: trace.creds ? "s3cret" : "",
			saslDisconnectOnFail: trace.required,
			ids: new IdAllocator(),
			transportFactory: () => transport,
			highlights: () => ({keywords: [], exceptions: []}),
			onSaslRejected: () => rejected++,
		});
		if (trace.trusted) {
			trustLogin(client.uuid, "alice");
		}

		client.connect();
		transport.open();

		const seen = (): string[] =>
			transport.sent.map(modelOf).filter((l): l is string => l !== null);
		const check = (upto: number): {expected: string[]; actual: string[]; at: number} | null => {
			const expected = canonical(trace.sent.slice(0, upto).map(show));
			const actual = canonical(seen());
			return JSON.stringify(expected) === JSON.stringify(actual)
				? null
				: {expected, actual, at: upto};
		};

		for (const ev of trace.got) {
			const bad = check(ev.at);

			if (bad) {
				return bad;
			}

			if (ev.m.t === "TIMER") {
				clock.tick(SASL_TIMEOUT_MS + 1);
			} else if (transport.state === "open") {
				transport.line(serverLine(ev.m));
			}
		}

		const bad = check(trace.sent.length);

		if (bad) {
			return bad;
		}

		// A refusal and a retry send the same QUIT; only this tells them apart.
		const seance = outcomeOf(rejected, transport);
		return seance === trace.outcome ? null : {outcome: trace.outcome, seance};
	} finally {
		clock.restore();
		socket.removeAllListeners();
	}
}

function describeTrace(trace: Trace): string {
	const seq = trace.got.map((g) => show(g.m)).join(" ");
	return `creds=${trace.creds} required=${trace.required}: ${seq}`;
}

function load(file: string): Trace[] {
	return JSON.parse(fs.readFileSync(path.join(__dirname, file), "utf8")) as Trace[];
}

describe("formal: handshake model replayed into IrcClient", function () {
	afterEach(function () {
		useStorageBackend(null);
	});

	it("Seance sends what the model's Seance sends, in every behaviour", function () {
		const traces = load("handshake.traces.json");
		expect(traces.length, "no traces: run gen.sh").to.be.greaterThan(100);
		const failures = traces.map((t) => ({t, bad: replay(t)})).filter((r) => r.bad !== null);

		expect(
			failures.map((f) => ({trace: describeTrace(f.t), ...f.bad})),
			`${failures.length} of ${traces.length} behaviours disagree`
		).to.deep.equal([]);
	});
});
